    css: "@font-face {\n  font-family: 'Source Serif 4';\n  font-style: normal;\n  font-weight: 400;\n  font-display: block;\n  src: url(data:font/woff2;base64,) format('woff2');\n}\n@font-face {\n  font-family: 'Source Serif 4';\n  font-style: normal;\n  font-weight: 700;\n  font-display: block;\n  src: url(data:font/woff2;base64,) format('woff2');\n}",
